28: char **
29: v4l2_list_cameras(int *num_devices)
30: {
31:     char **devices;
32:     char *device = NULL;
33:     int num, i, fd;
34: 
35:     num = *num_devices = 0;
36: 
37:     devices = (char **)malloc(sizeof(char *) * 65);
38:     if (!devices) {
39:         return NULL;
40:     }
41: 
42:     /* v4l2 cameras can be /dev/video and /dev/video0 to /dev/video63 */
43:     for (i = -1; i < 64; i++) {
44:         device = (char *)malloc(sizeof(char) * 13);
45:         if (!device) {
46:             goto error;
47:         }
48: 
49:         if (i == -1) {
50:             strcpy(device, "/dev/video");
51:         }
52:         else {
53:             int ret = PyOS_snprintf(device, 13, "/dev/video%d", i);
54:             if (ret < 0 || ret >= 13) {
55:                 goto error;
56:             }
57:         }
58: 
59:         fd = open(device, O_RDONLY | O_NONBLOCK);
60:         if (fd == -1) {
61:             free(device);
62:         }
63:         else {
64:             /* First clean the opened file before putting the name into the
65:              * array */
66:             if (close(fd) == -1) {
67:                 /* Error while closing file */
68:                 goto error;
69:             }
70: 
71:             /* 'device' is in array now, don't free it here */
72:             devices[num] = device;
73:             num++;
74:         }
75:     }
76: 
77:     *num_devices = num;
78:     return devices;
79: 
80: error:
81:     /* During goto here, 'device' must be either NULL or free-able allocated
82:      * memory */
83:     free(device);
84: 
85:     /* free individual 'device' already in devices array */
86:     for (i = 0; i < num; i++) {
87:         free(devices[i]);
88:     }
89:     free(devices);
90:     return NULL;
91: }
