93: /* A wrapper around a VIDIOC_S_FMT ioctl to check for format compatibility */
94: int
95: v4l2_pixelformat(int fd, struct v4l2_format *fmt, unsigned long pixelformat)
96: {
97:     fmt->fmt.pix.pixelformat = pixelformat;
98: 
99:     if (-1 == v4l2_xioctl(fd, VIDIOC_S_FMT, fmt)) {
100:         return 0;
101:     }
102: 
103:     if (fmt->fmt.pix.pixelformat == pixelformat) {
104:         return 1;
105:     }
106:     else {
107:         return 0;
108:     }
109: }
