147: PyObject *
148: v4l2_read_raw(pgCameraObject *self)
149: {
150:     struct v4l2_buffer buf;
151:     PyObject *raw;
152: 
153:     CLEAR(buf);
154: 
155:     buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
156:     buf.memory = V4L2_MEMORY_MMAP;
157: 
158:     if (-1 == v4l2_xioctl(self->fd, VIDIOC_DQBUF, &buf)) {
159:         PyErr_Format(PyExc_SystemError, "ioctl(VIDIOC_DQBUF) failure : %d, %s",
160:                      errno, strerror(errno));
161:         return NULL;
162:     }
163: 
164:     assert(buf.index < self->n_buffers);
165: 
166:     raw = PyBytes_FromStringAndSize(self->buffers[buf.index].start,
167:                                     self->buffers[buf.index].length);
168: 
169:     if (-1 == v4l2_xioctl(self->fd, VIDIOC_QBUF, &buf)) {
170:         PyErr_Format(PyExc_SystemError, "ioctl(VIDIOC_QBUF) failure : %d, %s",
171:                      errno, strerror(errno));
172:         return NULL;
173:     }
174:     return raw;
175: }
