186: int
187: v4l2_xioctl(int fd, int request, void *arg)
188: {
189:     int r;
190: 
191:     do
192:         r = ioctl(fd, request, arg);
193:     while (-1 == r && EINTR == errno);
194: 
195:     return r;
196: }
