390: /* This function is safe to be called with GIL released */
391: int
392: v4l2_read_frame(pgCameraObject *self, SDL_Surface *surf, int *errno_code)
393: {
394:     struct v4l2_buffer buf;
395: 
396:     CLEAR(buf);
397: 
398:     buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
399:     buf.memory = V4L2_MEMORY_MMAP;
400: 
401:     if (-1 == v4l2_xioctl(self->fd, VIDIOC_DQBUF, &buf)) {
402:         *errno_code = errno;
403:         return 0;
404:     }
405: 
406:     assert(buf.index < self->n_buffers);
407: 
408:     if (!v4l2_process_image(self, self->buffers[buf.index].start,
409:                             self->buffers[buf.index].length, surf)) {
410:         return 0;
411:     }
412: 
413:     if (-1 == v4l2_xioctl(self->fd, VIDIOC_QBUF, &buf)) {
414:         *errno_code = errno;
415:         return 0;
416:     }
417:     return 1;
418: }
