564: int
565: v4l2_init_device(pgCameraObject *self)
566: {
567:     struct v4l2_capability cap;
568:     struct v4l2_format fmt;
569:     unsigned int min;
570: 
571:     if (-1 == v4l2_xioctl(self->fd, VIDIOC_QUERYCAP, &cap)) {
572:         if (EINVAL == errno) {
573:             PyErr_Format(PyExc_SystemError, "%s is not a V4L2 device",
574:                          self->device_name);
575:             return 0;
576:         }
577:         else {
578:             PyErr_Format(PyExc_SystemError,
579:                          "ioctl(VIDIOC_QUERYCAP) failure : %d, %s", errno,
580:                          strerror(errno));
581:             return 0;
582:         }
583:     }
584: 
585:     if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
586:         PyErr_Format(PyExc_SystemError, "%s is not a video capture device",
587:                      self->device_name);
588:         return 0;
589:     }
590: 
591:     if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
592:         PyErr_Format(PyExc_SystemError, "%s does not support streaming i/o",
593:                      self->device_name);
594:         return 0;
595:     }
596: 
597:     CLEAR(fmt);
598: 
599:     fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
600:     fmt.fmt.pix.width = self->width;
601:     fmt.fmt.pix.height = self->height;
602:     fmt.fmt.pix.field = V4L2_FIELD_ANY;
603: 
604:     /* Find the pixelformat supported by the camera that will take the least
605:        processing power to convert to the desired output.  Thus, for YUV out,
606:        YUYVand YUV420 are first, while for RGB and HSV, the packed RGB formats
607:        are first. */
608:     switch (self->color_out) {
609:         case YUV_OUT:
610:             if (v4l2_pixelformat(self->fd, &fmt, V4L2_PIX_FMT_YUYV)) {
611:                 self->pixelformat = V4L2_PIX_FMT_YUYV;
612:             }
613:             else if (v4l2_pixelformat(self->fd, &fmt, V4L2_PIX_FMT_YUV420)) {
614:                 self->pixelformat = V4L2_PIX_FMT_YUV420;
615:             }
616:             else if (v4l2_pixelformat(self->fd, &fmt, V4L2_PIX_FMT_UYVY)) {
617:                 self->pixelformat = V4L2_PIX_FMT_UYVY;
618:             }
619:             else if (v4l2_pixelformat(self->fd, &fmt, V4L2_PIX_FMT_RGB24)) {
620:                 self->pixelformat = V4L2_PIX_FMT_RGB24;
621:             }
622:             else if (v4l2_pixelformat(self->fd, &fmt, V4L2_PIX_FMT_RGB444)) {
623:                 self->pixelformat = V4L2_PIX_FMT_RGB444;
624:             }
625:             else if (v4l2_pixelformat(self->fd, &fmt, V4L2_PIX_FMT_SBGGR8)) {
626:                 self->pixelformat = V4L2_PIX_FMT_SBGGR8;
627:             }
628:             else {
629:                 PyErr_Format(
630:                     PyExc_SystemError,
631:                     "ioctl(VIDIOC_S_FMT) failure: no supported formats");
632:                 return 0;
633:             }
634:             break;
635:         default:
636:             if (v4l2_pixelformat(self->fd, &fmt, V4L2_PIX_FMT_RGB24)) {
637:                 self->pixelformat = V4L2_PIX_FMT_RGB24;
638:             }
639:             else if (v4l2_pixelformat(self->fd, &fmt, V4L2_PIX_FMT_RGB444)) {
640:                 self->pixelformat = V4L2_PIX_FMT_RGB444;
641:             }
642:             else if (v4l2_pixelformat(self->fd, &fmt, V4L2_PIX_FMT_YUYV)) {
643:                 self->pixelformat = V4L2_PIX_FMT_YUYV;
644:             }
645:             else if (v4l2_pixelformat(self->fd, &fmt, V4L2_PIX_FMT_SBGGR8)) {
646:                 self->pixelformat = V4L2_PIX_FMT_SBGGR8;
647:             }
648:             else if (v4l2_pixelformat(self->fd, &fmt, V4L2_PIX_FMT_YUV420)) {
649:                 self->pixelformat = V4L2_PIX_FMT_YUV420;
650:             }
651:             else if (v4l2_pixelformat(self->fd, &fmt, V4L2_PIX_FMT_UYVY)) {
652:                 self->pixelformat = V4L2_PIX_FMT_UYVY;
653:             }
654:             else {
655:                 PyErr_Format(
656:                     PyExc_SystemError,
657:                     "ioctl(VIDIOC_S_FMT) failure: no supported formats");
658:                 return 0;
659:             }
660:             break;
661:     }
662: 
663:     /* Note VIDIOC_S_FMT may change width and height. */
664:     self->width = fmt.fmt.pix.width;
665:     self->height = fmt.fmt.pix.height;
666:     self->size = self->width * self->height;
667:     self->pixelformat = fmt.fmt.pix.pixelformat;
668: 
669:     /* Buggy driver paranoia. */
670:     min = fmt.fmt.pix.width * 2;
671:     if (fmt.fmt.pix.bytesperline < min)
672:         fmt.fmt.pix.bytesperline = min;
673:     min = fmt.fmt.pix.bytesperline * fmt.fmt.pix.height;
674:     if (fmt.fmt.pix.sizeimage < min)
675:         fmt.fmt.pix.sizeimage = min;
676: 
677:     v4l2_init_mmap(self);
678: 
679:     return 1;
680: }
