156: /**
157:  * \brief System message filter function -- handles X11 clipboard messages.
158:  *
159:  * \param event The SDL_Event to check.
160:  * \return Always 1.
161:  */
162: static int
163: _clipboard_filter(const SDL_Event *event)
164: {
165:     PyObject *dict = NULL;
166:     Time timestamp = CurrentTime;
167: 
168:     /* Post all non-window manager specific events */
169:     if (event->type != SDL_SYSWMEVENT)
170:         return 1;
171: 
172:     XEvent xevent = event->syswm.msg->event.xevent;
173: 
174:     /* Handle window-manager specific clipboard events */
175:     switch (xevent.type) {
176:         case PropertyNotify: {
177:             /* Handled in pygame_scrap_put(). */
178:             break;
179:         }
180:         case SelectionClear: {
181:             XSelectionClearEvent *clear = &xevent.xselectionclear;
182: 
183:             /* Looks like another window takes control over the clipboard.
184:              * Release the internally saved buffer, if any.
185:              */
186:             if (clear->selection == XA_PRIMARY)
187:                 timestamp = _selectiontime;
188:             else if (clear->selection == _atom_CLIPBOARD)
189:                 timestamp = _cliptime;
190:             else
191:                 break;
192: 
193:             /* Do not do anything, if the times do not match. */
194:             if (timestamp != CurrentTime &&
195:                 xevent.xselectionclear.time < timestamp)
196:                 break;
197: 
198:             /* Clean the dictionaries. */
199:             if (clear->selection == XA_PRIMARY)
200:                 PyDict_Clear(_selectiondata);
201:             else if (clear->selection != _atom_CLIPBOARD)
202:                 PyDict_Clear(_clipdata);
203:             break;
204:         }
205:         case SelectionNotify:
206:             /* This one will be handled directly in the pygame_scrap_get ()
207:              * function.
208:              */
209:             break;
210: 
211:         case SelectionRequest: {
212:             XSelectionRequestEvent *req = &xevent.xselectionrequest;
213:             XEvent ev;
214: 
215:             /* Prepare answer. */
216:             ev.xselection.type = SelectionNotify;
217:             ev.xselection.display = req->display;
218:             ev.xselection.requestor = req->requestor;
219:             ev.xselection.selection = req->selection;
220:             ev.xselection.target = req->target;
221:             ev.xselection.property = None;
222:             ev.xselection.time = req->time;
223: 
224:             /* Which clipboard type was requested? */
225:             if (req->selection == XA_PRIMARY) {
226:                 dict = _selectiondata;
227:                 timestamp = _selectiontime;
228:             }
229:             else if (req->selection == _atom_CLIPBOARD) {
230:                 dict = _clipdata;
231:                 timestamp = _cliptime;
232:             }
233:             else /* Anything else's not supported. */
234:             {
235:                 XSendEvent(req->display, req->requestor, False, NoEventMask,
236:                            &ev);
237:                 return 1;
238:             }
239: 
240:             /* No data? */
241:             if (PyDict_Size(dict) == 0) {
242:                 XSendEvent(req->display, req->requestor, False, NoEventMask,
243:                            &ev);
244:                 return 1;
245:             }
246: 
247:             /* We do not own the selection anymore. */
248:             if (timestamp == CurrentTime ||
249:                 (req->time != CurrentTime && timestamp > req->time)) {
250:                 XSendEvent(req->display, req->requestor, False, NoEventMask,
251:                            &ev);
252:                 return 1;
253:             }
254: 
255:             /*
256:              * TODO: We have to make it ICCCM compatible at some point by
257:              * implementing the MULTIPLE atom request.
258:              */
259: 
260:             /* Old client? */
261:             if (req->property == None)
262:                 ev.xselection.property = req->target;
263: 
264:             if (req->target == _atom_TARGETS) {
265:                 /* The requestor wants to know, what we've got. */
266:                 _set_targets(dict, req->display, req->requestor,
267:                              req->property);
268:             }
269:             else {
270:                 _set_data(dict, req->display, req->requestor, req->property,
271:                           req->target);
272:             }
273: 
274:             ev.xselection.property = req->property;
275:             /* Post the event for X11 clipboard reading above */
276:             XSendEvent(req->display, req->requestor, False, 0, &ev);
277:             break;
278:         }
279:     }
280:     return 1;
281: }
