397: /**
398:  * Retrieves the data from a certain source Atom using a specific
399:  * format.
400:  *
401:  * \param source The currently active clipboard Atom to get the data from.
402:  * \param format The format of the data to get.
403:  * \param length Out parameter that contains the length of the returned
404:  * buffer.
405:  * \return The requested content or NULL in case no content exists or an
406:  * error occurred.
407:  */
408: static char *
409: _get_data_as(Atom source, Atom format, unsigned long *length)
410: {
411:     unsigned char *retval = NULL;
412:     Window owner;
413:     time_t start;
414:     Atom sel_type;
415:     int sel_format;
416:     unsigned long nbytes;
417:     unsigned long overflow;
418:     *length = 0;
419:     unsigned char *src;
420:     unsigned long offset = 0;
421:     unsigned long chunk = 0;
422:     int step = 1;
423:     XEvent ev;
424:     Time timestamp;
425: 
426:     /* If we are the owner, simply return the clip buffer, if it matches
427:      * the request type.
428:      */
429:     if (!pygame_scrap_lost()) {
430:         char *fmt;
431:         char *data;
432: 
433:         fmt = _atom_to_string(format);
434: 
435:         if (_currentmode == SCRAP_SELECTION)
436:             data = PyBytes_AsString(PyDict_GetItemString(_selectiondata, fmt));
437:         else
438:             data = PyBytes_AsString(PyDict_GetItemString(_clipdata, fmt));
439:         free(fmt);
440: 
441:         return data;
442:     }
443: 
444:     Lock_Display();
445: 
446:     /* Find a selection owner. */
447:     owner = _get_scrap_owner(&source);
448:     if (owner == None) {
449:         Unlock_Display();
450:         return NULL;
451:     }
452: 
453:     timestamp = (source == XA_PRIMARY) ? _selectiontime : _cliptime;
454: 
455:     /* Copy and convert the selection into our SDL_SELECTION atom of the
456:      * window.
457:      * Flush afterwards, so we have an immediate effect and do not receive
458:      * the old buffer anymore.
459:      */
460:     XConvertSelection(SDL_Display, source, format, _atom_SDL, SDL_Window,
461:                       timestamp);
462:     XSync(SDL_Display, False);
463: 
464:     /* Let's wait for the SelectionNotify event from the callee and
465:      * react upon it as soon as it is received.
466:      */
467:     for (start = time(0);;) {
468:         if (XCheckTypedWindowEvent(SDL_Display, SDL_Window, SelectionNotify,
469:                                    &ev))
470:             break;
471:         if (time(0) - start >= 5) {
472:             /* Timeout, damn. */
473:             Unlock_Display();
474:             return NULL;
475:         }
476:     }
477: 
478:     /* Get any property type and check the sel_type afterwards to decide
479:      * what to do.
480:      */
481:     if (XGetWindowProperty(SDL_Display, ev.xselection.requestor, _atom_SDL, 0,
482:                            0, True, AnyPropertyType, &sel_type, &sel_format,
483:                            &nbytes, &overflow, &src) != Success) {
484:         XFree(src);
485:         Unlock_Display();
486:         return NULL;
487:     }
488: 
489:     /* In case we requested a SCRAP_TEXT, any property type of
490:      * XA_STRING, XA_COMPOUND_TEXT, UTF8_STRING and TEXT is valid.
491:      */
492:     if (format == _atom_MIME_PLAIN &&
493:         (sel_type != _atom_UTF8 && sel_type != _atom_TEXT &&
494:          sel_type != _atom_COMPOUND && sel_type != XA_STRING)) {
495:         /* No matching text type found. Return nothing then. */
496:         XFree(src);
497:         Unlock_Display();
498:         return NULL;
499:     }
500: 
501:     /* Anything is fine, so copy the buffer and return it. */
502:     switch (sel_format) {
503:         case 16:
504:             step = sizeof(short) / 2;
505:             break;
506:         case 32:
507:             step = sizeof(long) / 4;
508:             break;
509:         case 8:
510:         default:
511:             step = sizeof(char);
512:             *length =
513:                 overflow; /* 8 bit size is already correctly set in nbytes.*/
514:             break;
515:     }
516: 
517:     /* X11 guarantees NULL termination, add an extra byte. */
518:     *length = step * overflow;
519:     retval = malloc(*length + 1);
520:     if (retval) {
521:         unsigned long boffset = 0;
522:         chunk = MAX_CHUNK_SIZE(SDL_Display);
523:         memset(retval, 0, (size_t)(*length + 1));
524: 
525:         /* Read as long as there is data. */
526:         while (overflow) {
527:             if (XGetWindowProperty(SDL_Display, ev.xselection.requestor,
528:                                    _atom_SDL, offset, chunk, True,
529:                                    AnyPropertyType, &sel_type, &sel_format,
530:                                    &nbytes, &overflow, &src) != Success) {
531:                 break;
532:             }
533: 
534:             offset += nbytes / (32 / sel_format);
535:             nbytes *= step * sel_format / 8;
536:             memcpy(retval + boffset, src, nbytes);
537:             boffset += nbytes;
538:             XFree(src);
539:         }
540:     }
541:     else {
542:         /* ENOMEM */
543:         return NULL;
544:     }
545: 
546:     /* In case we've got a COMPOUND_TEXT, convert it to the current
547:      * multibyte locale.
548:      */
549:     if (sel_type == _atom_COMPOUND && sel_format == 8) {
550:         char **list = NULL;
551:         int count;
552:         int status = 0;
553:         XTextProperty p;
554: 
555:         p.encoding = sel_type;
556:         p.format = sel_format;
557:         p.nitems = nbytes;
558:         p.value = retval;
559: 
560:         status = XmbTextPropertyToTextList(SDL_Display, &p, &list, &count);
561:         if (status == XLocaleNotSupported || status == XConverterNotFound) {
562:             free(retval);
563:             PyErr_SetString(pgExc_SDLError,
564:                             "current locale is not supported for conversion.");
565:             return NULL;
566:         }
567:         else if (status == XNoMemory) {
568:             free(retval);
569:             return NULL;
570:         }
571:         else if (status == Success) {
572:             if (count && list) {
573:                 int i = 0;
574:                 int ioffset = 0;
575:                 unsigned char *tmp;
576: 
577:                 free(retval);
578:                 retval = NULL;
579:                 for (i = 0; i < count; i++) {
580:                     *length = strlen(list[i]);
581:                     tmp = retval;
582:                     retval = realloc(retval, (*length) + 1);
583:                     if (!retval) {
584:                         free(tmp);
585:                         return NULL;
586:                     }
587:                     ioffset += *length;
588: 
589:                     memcpy(retval, list[i], *length);
590:                     memset(retval + ioffset, '\n', 1);
591:                 }
592:                 memset(retval + ioffset, 0, 1);
593:             }
594:         }
595: 
596:         if (list)
597:             XFreeStringList(list);
598:     }
599: 
600:     Unlock_Display();
601:     return (char *)retval;
602: }
