613:     SDL_VERSION(&info.version);
614:     if (SDL_GetWMInfo(&info)) {
615:         /* Save the information for later use */
616:         if (info.subsystem == SDL_SYSWM_X11) {
617:             XWindowAttributes setattrs;
618:             XSetWindowAttributes newattrs;
619: 
620:             newattrs.event_mask = PropertyChangeMask;
