675: int
676: pygame_scrap_put(char *type, Py_ssize_t srclen, char *src)
677: {
678:     Atom clip;
679:     Atom cliptype;
680:     Time timestamp = CurrentTime;
681:     time_t start;
682:     XEvent ev;
683: 
684:     if (!pygame_scrap_initialized()) {
685:         PyErr_SetString(pgExc_SDLError, "scrap system not initialized.");
686:         return 0;
687:     }
688: 
689:     Lock_Display();
690: 
691:     clip = GET_CLIPATOM(_currentmode);
692:     cliptype = _convert_format(type);
693: 
694:     /* We've some types which should not be set by the user. */
695:     if (cliptype == _atom_TARGETS || cliptype == _atom_SDL ||
696:         cliptype == _atom_TIMESTAMP) {
697:         PyErr_SetString(PyExc_ValueError, "the requested type is reserved.");
698:         Unlock_Display();
699:         return 0;
700:     }
701: 
702:     /* Update the clipboard property with the buffer. */
703:     XChangeProperty(SDL_Display, SDL_Window, clip, cliptype, 8,
704:                     PropModeReplace, (unsigned char *)src, srclen);
705: 
706:     if (cliptype == _atom_MIME_PLAIN) {
707:         /* Set PYGAME_SCRAP_TEXT. Also set XA_STRING, TEXT and
708:          * UTF8_STRING if they are not set in the dictionary.
709:          */
710:         _add_clip_data(XA_STRING, src, srclen);
711:         _add_clip_data(_atom_UTF8, src, srclen);
712:         _add_clip_data(_atom_TEXT, src, srclen);
713:     }
714:     XSync(SDL_Display, False);
715: 
716:     /* Update the timestamp */
717:     for (start = time(0);;) {
718:         if (XCheckTypedWindowEvent(SDL_Display, SDL_Window, PropertyNotify,
719:                                    &ev))
720:             break;
721:         if (time(0) - start >= 5) {
722:             /* Timeout, damn. */
723:             Unlock_Display();
724:             goto SETSELECTIONOWNER;
725:         }
726:     }
727:     if (ev.xproperty.atom == clip) {
728:         timestamp = ev.xproperty.time;
729: 
730:         if (clip == XA_PRIMARY)
731:             _selectiontime = timestamp;
732:         else
733:             _cliptime = timestamp;
734:     }
735:     else
736:         timestamp = (clip == XA_PRIMARY) ? _selectiontime : _cliptime;
737: 
738: SETSELECTIONOWNER:
739:     /* Set the selection owner to the own window. */
740:     XSetSelectionOwner(SDL_Display, clip, SDL_Window, timestamp);
741:     if (XGetSelectionOwner(SDL_Display, clip) != SDL_Window) {
742:         /* Ouch, we could not toggle the selection owner. Raise an
743:          * error, as it's not guaranteed, that the clipboard
744:          * contains valid data.
745:          */
746:         Unlock_Display();
747:         return 0;
748:     }
749: 
750:     Unlock_Display();
751:     return 1;
752: }
