76: static size_t
77: _lookup_clipboard_format(UINT format, char *buf, int size)
78: {
79:     size_t len;
80:     char *cpy;
81: 
82:     memset(buf, 0, size);
83:     switch (format) {
84:         case CF_TEXT:
85:             len = strlen(PYGAME_SCRAP_TEXT);
86:             cpy = PYGAME_SCRAP_TEXT;
87:             break;
88:         case CF_UNICODETEXT:
89:             len = 24;
90:             cpy = "text/plain;charset=utf-8";
91:             break;
92:         case CF_TIFF:
93:             len = 10;
94:             cpy = "image/tiff";
95:             break;
96:         case CF_DIB:
97:             len = strlen(PYGAME_SCRAP_BMP);
98:             cpy = PYGAME_SCRAP_BMP;
99:             break;
100:         case CF_WAVE:
101:             len = 9;
102:             cpy = "audio/wav";
103:             break;
104:         default:
105:             len = GetClipboardFormatName(format, buf, size);
106:             return len;
107:     }
108:     if (len != 0)
109:         memcpy(buf, cpy, len);
110:     return len;
