243: char *
244: pygame_scrap_get(char *type, size_t *count)
245: {
246:     UINT format = _convert_format(type);
247:     char *retval = NULL;
248: 
249:     if (!pygame_scrap_initialized()) {
250:         PyErr_SetString(pgExc_SDLError, "scrap system not initialized.");
251:         return NULL;
252:     }
253: 
254:     if (!pygame_scrap_lost())
255:         return PyBytes_AsString(PyDict_GetItemString(_clipdata, type));
256: 
257:     if (!OpenClipboard(window_handle))
258:         return NULL;
259: 
260:     if (!IsClipboardFormatAvailable(format)) {
261:         /* The format was not found - was it a mapped type? */
262:         format = _convert_internal_type(type);
263:         if (format == -1) {
264:             CloseClipboard();
265:             return NULL;
266:         }
267:     }
268: 
269:     if (IsClipboardFormatAvailable(format)) {
270:         HANDLE hMem;
271:         char *src;
272:         src = NULL;
273: 
274:         hMem = GetClipboardData(format);
275:         if (hMem) {
276:             *count = 0;
277: 
278:             /* CF_BITMAP is not a global, so do not lock it. */
279:             if (format != CF_BITMAP) {
280:                 src = GlobalLock(hMem);
281:                 if (!src) {
282:                     CloseClipboard();
283:                     return NULL;
284:                 }
285:                 *count = GlobalSize(hMem);
286:             }
287: 
288:             if (format == CF_DIB || format == CF_DIBV5) {
289:                 /* Count will be increased accordingly in
290:                  * _create_dib_buffer.
291:                  */
292:                 src = _create_dib_buffer(src, count);
293:                 GlobalUnlock(hMem);
294:                 CloseClipboard();
295:                 return src;
296:             }
297:             else if (*count != 0) {
298:                 /* weird error, shouldn't get here. */
299:                 if (!src) {
300:                     return NULL;
301:                 }
302: 
303:                 retval = malloc(*count);
304:                 if (retval) {
305:                     memset(retval, 0, *count);
306:                     memcpy(retval, src, *count);
307:                 }
308:             }
309:             GlobalUnlock(hMem);
310:         }
311:     }
312: 
313:     CloseClipboard();
314:     return retval;
315: }
