20: /*
21:  * Camera - webcam support for pygame
22:  * Author: Nirav Patel
23:  *
24:  * This module allows for use of v4l2 webcams in pygame. The code is written
25:  * such that adding support for vfw cameras should be possible without
26:  * much modification of existing functions. v4l2 functions are kept separate
27:  * from functions available to pygame users and generic functions like
28:  * colorspace conversion.
29:  *
30:  * There is currently support for cameras that support MMAP and use
31:  * pixelformats of RGB24, RGB444, YUYV, SBGGR8, and YUV420. To add support for
32:  * additional pixelformats, add them to v4l2_init_device and
33:  * v4l2_process_image, and add functions to convert the format to packed RGB,
34:  * YUV, and HSV.
35:  */
36: 
37: #include "camera.h"
38: #include "pgcompat.h"
39: 
40: /*
41: #if defined(__unix__) || !defined(__APPLE__)
42: #else
43:     #define V4L2_PIX_FMT_RGB24 1
44:     #define V4L2_PIX_FMT_RGB444 1
45: #endif
46: */
47: 
48: /* functions available to pygame users */
49: PyObject *
50: surf_colorspace(PyObject *self, PyObject *arg);
51: PyObject *
52: list_cameras(PyObject *self, PyObject *arg);
53: PyObject *
54: camera_start(pgCameraObject *self, PyObject *args);
55: PyObject *
56: camera_stop(pgCameraObject *self, PyObject *args);
57: PyObject *
58: camera_get_controls(pgCameraObject *self, PyObject *args);
59: PyObject *
60: camera_set_controls(pgCameraObject *self, PyObject *arg, PyObject *kwds);
61: PyObject *
62: camera_get_size(pgCameraObject *self, PyObject *args);
63: PyObject *
64: camera_query_image(pgCameraObject *self, PyObject *args);
65: PyObject *
66: camera_get_image(pgCameraObject *self, PyObject *arg);
67: PyObject *
68: camera_get_raw(pgCameraObject *self, PyObject *args);
69: 
70: /*
71:  * Functions available to pygame users.  The idea is to make these as simple as
72:  * possible, and merely have them call functions specific to the type of
73:  * camera being used to do all the real work.  It currently just calls v4l2_*
74:  * functions, but it could check something like self->cameratype and depending
75:  * on the result, call v4l, v4l2, vfw, or other functions.
76:  */
77: 
78: /* colorspace() - Surface colorspace conversion */
79: PyObject *
80: surf_colorspace(PyObject *self, PyObject *arg)
81: {
82:     pgSurfaceObject *surfobj, *surfobj2;
83:     SDL_Surface *surf, *newsurf;
84:     char *color;
85:     int cspace;
86:     surfobj2 = NULL;
87: 
88: #ifdef _MSC_VER
89:     /* MSVC static analyzer false alarm: assure color is NULL-terminated by
90:      * making analyzer assume it was initialised */
91:     __analysis_assume(color = "inited");
92: #endif
93: 
94:     /*get all the arguments*/
95:     if (!PyArg_ParseTuple(arg, "O!s|O!", &pgSurface_Type, &surfobj, &color,
96:                           &pgSurface_Type, &surfobj2))
97:         return NULL;
98: 
99:     if (!strcmp(color, "YUV")) {
100:         cspace = YUV_OUT;
101:     }
102:     else if (!strcmp(color, "HSV")) {
103:         cspace = HSV_OUT;
104:     }
105:     else {
106:         return RAISE(PyExc_ValueError, "Incorrect colorspace value");
107:     }
108: 
109:     surf = pgSurface_AsSurface(surfobj);
110: 
111:     if (!surf)
112:         return RAISE(pgExc_SDLError, "display Surface quit");
113: 
114:     if (!surfobj2) {
115:         newsurf = SDL_CreateRGBSurface(
116:             0, surf->w, surf->h, surf->format->BitsPerPixel,
117:             surf->format->Rmask, surf->format->Gmask, surf->format->Bmask,
118:             surf->format->Amask);
119:         if (!newsurf) {
120:             return NULL;
121:         }
122:     }
123:     else {
124:         newsurf = pgSurface_AsSurface(surfobj2);
125:         if (!newsurf)
126:             return RAISE(pgExc_SDLError, "display Surface quit");
127:     }
128: 
129:     /* check to see if the size is the same. */
130:     if (newsurf->w != surf->w || newsurf->h != surf->h)
131:         return RAISE(PyExc_ValueError,
132:                      "Surfaces not the same width and height.");
133: 
134:     /* check to see if the format of the surface is the same. */
135:     if (surf->format->BitsPerPixel != newsurf->format->BitsPerPixel)
136:         return RAISE(PyExc_ValueError, "Surfaces not the same depth");
137: 
138:     SDL_LockSurface(newsurf);
139:     pgSurface_Lock(surfobj);
140: 
141:     Py_BEGIN_ALLOW_THREADS;
142:     colorspace(surf, newsurf, cspace);
143:     Py_END_ALLOW_THREADS;
144: 
145:     pgSurface_Unlock(surfobj);
146:     SDL_UnlockSurface(newsurf);
147: 
148:     if (surfobj2) {
149:         Py_INCREF(surfobj2);
150:         return (PyObject *)surfobj2;
151:     }
152:     else
153:         return (PyObject *)pgSurface_New(newsurf);
154: }
