156: /* list_cameras() - lists cameras available on the computer */
157: PyObject *
158: list_cameras(PyObject *self, PyObject *_null)
159: {
160: #if defined(__unix__)
161:     PyObject *ret_list;
162:     PyObject *string;
163:     char **devices;
164:     int j, i = 0, num_devices = 0;
165: 
166:     /* TODO for future PRs: errors in these functions are being ignored as
167:      * of now, and an empty list is being returned by this function */
168: #if defined(__unix__)
169:     devices = v4l2_list_cameras(&num_devices);
170:     ret_list = PyList_New(num_devices);
171:     if (!ret_list) {
172:         goto error;
173:     }
174: 
175:     for (i = 0; i < num_devices; i++) {
176:         string = PyUnicode_FromString(devices[i]);
177: #endif
178:         if (!string) {
179:             goto error;
180:         }
181:         /* steals reference to 'string' */
182:         PyList_SET_ITEM(ret_list, i, string);
183:         free(devices[i]);
184:     }
185:     free(devices);
186: 
187:     return ret_list;
188: error:
189:     /* free the remaining devices */
190:     for (j = i; j < num_devices; j++) {
191:         free(devices[j]);
192:     }
193:     free(devices);
194:     Py_XDECREF(ret_list);
195:     return NULL;
196: 
197: #else
198:     Py_RETURN_NONE;
199: #endif
200: }

